scenarios.example_code:
import { installConnector } from '@projexlight/connector-microsoft365';
const { install_id } = await installConnector({
  tenant_id, m365_tenant_id, auth_code,
  scopes: ['Files.Read.All','Calendars.Read','ChatMessage.Send'],
});

import { syncDrive } from '@projexlight/connector-microsoft365';
await syncDrive({
  install_id, drive_id, folder_path: '/Contracts',
  use_delta_token: true,
});

import { postTeamsMessage } from '@projexlight/connector-microsoft365';
await postTeamsMessage({
  install_id, team_id, channel_id,
  text: '🚨 Storm declared — see ProjexCloud for details', mention_team: true,
});

import { sendMail } from '@projexlight/connector-microsoft365';
await sendMail({
  install_id, sender_user_id, to: customer.email,
  subject: '...', body_html: '...',
});
